package org.apache.commons.jxpath.ri.model.jdom;

import org.jdom.CDATA;
import org.jdom.Element;
import org.jdom.Namespace;
import org.jdom.ProcessingInstruction;
import org.jdom.Text;
import org.junit.Test;

import java.util.Locale;

import static org.junit.Assert.*;

public class AsPathTests {

    @Test
    public void testAsPathUsesIdWhenPresentAndEscapesApostrophe() {
        JDOMNodePointer pointer = new JDOMNodePointer(new Element("dummy"), Locale.ENGLISH, "O'Brien");
        assertEquals("id('O\\'Brien')", pointer.asPath());
    }

    @Test
    public void testAsPathForRootElementWithoutNamespaceUsesLocalNameAndPosition() {
        Element root = new Element("root");
        JDOMNodePointer pointer = new JDOMNodePointer(root, Locale.ENGLISH);

        assertEquals("/root[1]", pointer.asPath());
    }

    @Test
    public void testAsPathForChildElementInSameTreeUsesParentPathAndQNamePosition() {
        Element root = new Element("root");
        Element child = new Element("child");
        root.addContent(child);

        JDOMNodePointer parentPointer = new JDOMNodePointer(root, Locale.ENGLISH);
        JDOMNodePointer childPointer = new JDOMNodePointer(parentPointer, child);

        assertEquals("/root[1]/child[1]", childPointer.asPath());
    }

    @Test
    public void testAsPathForNamespacedElementWithKnownPrefixUsesPrefixAndQNamePosition() {
        Namespace ns = Namespace.getNamespace("p", "http://example.com/ns");
        Element root = new Element("root", ns);
        JDOMNodePointer pointer = new JDOMNodePointer(root, Locale.ENGLISH);

        assertEquals("/p:root[1]", pointer.asPath());
    }

    @Test
    public void testAsPathForNamespacedElementWithoutPrefixUsesNodeTestAndElementPosition() {
        Namespace ns = Namespace.getNamespace("http://example.com/ns");
        Element root = new Element("root", ns);
        JDOMNodePointer pointer = new JDOMNodePointer(root, Locale.ENGLISH);

        assertEquals("/node()[1]", pointer.asPath());
    }

    @Test
    public void testAsPathForTextNodeUsesTextTestAndRelativePosition() {
        Text text = new Text("value");
        JDOMNodePointer pointer = new JDOMNodePointer(text, Locale.ENGLISH);

        assertEquals("/text()[1]", pointer.asPath());
    }

    @Test
    public void testAsPathForCdataNodeUsesTextTestAndRelativePosition() {
        CDATA cdata = new CDATA("value");
        JDOMNodePointer pointer = new JDOMNodePointer(cdata, Locale.ENGLISH);

        assertEquals("/text()[1]", pointer.asPath());
    }

    @Test
    public void testAsPathForProcessingInstructionUsesTargetAndRelativePosition() {
        ProcessingInstruction pi = new ProcessingInstruction("xml-stylesheet", "type='text/xsl'");
        JDOMNodePointer pointer = new JDOMNodePointer(pi, Locale.ENGLISH);

        assertEquals("/processing-instruction('xml-stylesheet')[1]", pointer.asPath());
    }

    @Test
    public void testAsPathForUnrecognizedNodeTypeReturnsParentPathOnly() {
        Object node = new Object();
        JDOMNodePointer pointer = new JDOMNodePointer(node, Locale.ENGLISH);

        assertEquals("", pointer.asPath());
    }

    @Test
    public void testAsPathDoesNotMutatePointerState() {
        Element root = new Element("root");
        JDOMNodePointer pointer = new JDOMNodePointer(root, Locale.ENGLISH);

        String before = pointer.asPath();
        String after = pointer.asPath();

        assertEquals(before, after);
        assertEquals("/root[1]", before);
    }
}

