import static org.junit.Assert.assertSame;

import java.lang.reflect.Field;
import java.lang.reflect.Method;

import org.junit.Test;

public class JjFillTokenTests {

    private static class TestableXPathParserTokenManager extends XPathParserTokenManager {
        TestableXPathParserTokenManager(SimpleCharStream stream) {
            super(stream);
        }

        Token callJjFillToken() {
            return super.jjFillToken();
        }
    }

    private static SimpleCharStream streamFor(String input) throws Exception {
        return new SimpleCharStream(new java.io.StringReader(input), 1, 1, input.length());
    }

    private static void setIntField(Object target, String fieldName, int value) throws Exception {
        Field f = target.getClass().getDeclaredField(fieldName);
        f.setAccessible(true);
        f.setInt(target, value);
    }

    private static int getIntField(Object target, String fieldName) throws Exception {
        Field f = target.getClass().getDeclaredField(fieldName);
        f.setAccessible(true);
        return f.getInt(target);
    }

    private static void setStreamState(SimpleCharStream stream, int beginLine, int beginColumn, int endLine, int endColumn)
            throws Exception {
        setIntField(stream, "bufline", 0);
        setIntField(stream, "bufcolumn", 0);
        Field tokenBegin = SimpleCharStream.class.getDeclaredField("tokenBegin");
        tokenBegin.setAccessible(true);
        tokenBegin.setInt(stream, 0);

        Field bufpos = SimpleCharStream.class.getDeclaredField("bufpos");
        bufpos.setAccessible(true);
        bufpos.setInt(stream, 0);

        Field lineField = SimpleCharStream.class.getDeclaredField("line");
        lineField.setAccessible(true);
