package org.apache.commons.jxpath.util;

import static org.junit.Assert.*;

import java.lang.reflect.Array;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;

import org.junit.Test;

public class IterateTests {

    @Test
    public void nullInputReturnsEmptyIterator() {
        Iterator it = ValueUtils.iterate(null);
        assertNotNull(it);
        assertFalse(it.hasNext());
    }

    @Test
    public void emptyArrayReturnsEmptyIterator() {
        Iterator it = ValueUtils.iterate(new String[0]);
        assertNotNull(it);
        assertFalse(it.hasNext());
    }

    @Test
    public void primitiveArrayIsIteratedInOrder() {
        int[] input = new int[] {1, 2, 3};
        Iterator it = ValueUtils.iterate(input);

        assertTrue(it.hasNext());
        assertEquals(1, ((Number) it.next()).intValue());
        assertTrue(it.hasNext());
        assertEquals(2, ((Number) it.next()).intValue());
        assertTrue(it.hasNext());
        assertEquals(3, ((Number) it.next()).intValue());
        assertFalse(it.hasNext());

        assertArrayEquals(new int[] {1, 2, 3}, input);
    }

    @Test
    public void objectArrayIsIteratedIncludingNullElements() {
        String[] input = new String[] {"a", null, "c"};
        Iterator it = ValueUtils.iterate(input);

        assertEquals("a", it.next());
        assertNull(it.next());
        assertEquals("c", it.next());
        assertFalse(it.hasNext());

        assertArrayEquals(new String[] {"a", null, "c"}, input);
    }

    @Test
    public void nonEmptyCollectionReturnsItsIterator() {
        List<String> input = new ArrayList<String>(Arrays.asList("x", "y"));
        Iterator it = ValueUtils.iterate(input);

        assertSame(input.iterator().getClass(), it.getClass());
        assertEquals("x", it.next());
        assertEquals("y", it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void emptyCollectionIsWrappedAsSingleElementIteratorContainingTheCollection() {
        List<String> input = new ArrayList<String>();
        Iterator it = ValueUtils.iterate(input);

        assertTrue(it.hasNext());
        assertSame(input, it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void singleObjectIsWrappedInSingletonIterator() {
        Object input = new Object();
        Iterator it = ValueUtils.iterate(input);

        assertTrue(it.hasNext());
        assertSame(input, it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void iteratorDoesNotModifySourceCollection() {
        List<String> input = new ArrayList<String>(Arrays.asList("a", "b"));
        Iterator it = ValueUtils.iterate(input);

        assertEquals("a", it.next());
        input.add("c");
        assertEquals("b", it.next());
        assertTrue(it.hasNext());
        assertEquals("c", it.next());
    }

    @Test
    public void multidimensionalArrayIsIteratedAsTopLevelElements() {
        String[][] input = new String[][] {{"a"}, {"b", "c"}};
        Iterator it = ValueUtils.iterate(input);

        assertArrayEquals(new String[] {"a"}, (String[]) it.next());
        assertArrayEquals(new String[] {"b", "c"}, (String[]) it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void collectionContainingNullIsIteratedCorrectly() {
        List<String> input = Arrays.asList("first", null, "third");
        Iterator it = ValueUtils.iterate(input);

        assertEquals("first", it.next());
        assertNull(it.next());
        assertEquals("third", it.next());
        assertFalse(it.hasNext());
    }
}

