package org.apache.commons.jxpath.util;

import static org.junit.Assert.*;

import java.lang.reflect.Array;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;

import org.junit.Test;

public class IterateTests {

    @Test
    public void testNullInputReturnsEmptyIterator() {
        Iterator it = ValueUtils.iterate(null);
        assertNotNull(it);
        assertFalse(it.hasNext());
    }

    @Test
    public void testEmptyObjectArrayReturnsEmptyIterator() {
        Iterator it = ValueUtils.iterate(new Object[0]);
        assertNotNull(it);
        assertFalse(it.hasNext());
    }

    @Test
    public void testMultiDimensionalArrayIsIteratedAsElements() {
        String[][] input = new String[][] { {"a", "b"}, {"c"} };
        Iterator it = ValueUtils.iterate(input);

        assertTrue(it.hasNext());
        assertArrayEquals(new String[] {"a", "b"}, (String[]) it.next());
        assertTrue(it.hasNext());
        assertArrayEquals(new String[] {"c"}, (String[]) it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void testPrimitiveArrayIsIteratedAsBoxedElementsInOrder() {
        int[] input = new int[] {1, 2, 3};
        Iterator it = ValueUtils.iterate(input);

        assertTrue(it.hasNext());
        assertEquals(1, it.next());
        assertTrue(it.hasNext());
        assertEquals(2, it.next());
        assertTrue(it.hasNext());
        assertEquals(3, it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void testPrimitiveBooleanArrayIsIteratedAsBoxedElements() {
        boolean[] input = new boolean[] {true, false, true};
        Iterator it = ValueUtils.iterate(input);

        assertTrue(it.hasNext());
        assertEquals(Boolean.TRUE, it.next());
        assertTrue(it.hasNext());
        assertEquals(Boolean.FALSE, it.next());
        assertTrue(it.hasNext());
        assertEquals(Boolean.TRUE, it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void testCollectionIterationUsesSnapshotIndependentOfLaterChanges() {
        List<String> input = new ArrayList<String>();
        input.add("x");
        input.add("y");

        Iterator it = ValueUtils.iterate(input);
        input.add("z");

        assertTrue(it.hasNext());
        assertEquals("x", it.next());
        assertTrue(it.hasNext());
        assertEquals("y", it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void testCollectionIterationDoesNotReflectEarlierIteratorRemoval() {
        List<String> input = new ArrayList<String>();
        input.add("a");
        input.add("b");
        input.add("c");

        Iterator it = ValueUtils.iterate(input);
        input.remove("b");

        assertEquals("a", it.next());
        assertEquals("b", it.next());
        assertEquals("c", it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void testSingleObjectIsWrappedAsSingletonIterator() {
        Object obj = new Object();
        Iterator it = ValueUtils.iterate(obj);

        assertTrue(it.hasNext());
        assertSame(obj, it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void testNullElementInObjectArrayIsPreserved() {
        String[] input = new String[] {"a", null, "c"};
        Iterator it = ValueUtils.iterate(input);

        assertEquals("a", it.next());
        assertNull(it.next());
        assertEquals("c", it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void testReturnedIteratorIsIndependentFromSourceArrayModification() {
        String[] input = new String[] {"p", "q"};
        Iterator it = ValueUtils.iterate(input);
        input[0] = "changed";
        input[1] = "also-changed";

        assertEquals("p", it.next());
        assertEquals("q", it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void testEmptyCollectionReturnsEmptyIterator() {
        Collection<String> input = Collections.emptyList();
        Iterator it = ValueUtils.iterate(input);
        assertNotNull(it);
        assertFalse(it.hasNext());
    }

    @Test
    public void testIteratorDoesNotExposeRemovalForArrayBackedIteration() {
        Iterator it = ValueUtils.iterate(new String[] {"a"});
        assertTrue(it.hasNext());
        assertEquals("a", it.next());
        try {
            it.remove();
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException expected) {
            // expected
        }
    }

    @Test
    public void testNestedArrayElementsAreReturnedAsSameReferences() {
        Object[] inner = new Object[] {"x"};
        Object[] input = new Object[] {inner};

        Iterator it = ValueUtils.iterate(input);
        assertTrue(it.hasNext());
        assertSame(inner, it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void testSingleNullObjectIsWrappedNotTreatedAsNullInput() {
        Object singleNull = new Object() {
            @Override
            public String toString() {
                return "null-object";
            }
        };
        Iterator it = ValueUtils.iterate(singleNull);

        assertTrue(it.hasNext());
        assertSame(singleNull, it.next());
        assertFalse(it.hasNext());
    }

    @Test
    public void testArrayInputRemainsUnchangedAfterIteration() {
        String[] input = new String[] {"alpha", "beta"};
        Iterator it = ValueUtils.iterate(input);

        assertEquals("alpha", it.next());
        assertEquals("beta", it.next());
        assertArrayEquals(new String[] {"alpha", "beta"}, input);
        assertFalse(it.hasNext());
    }
}

