        assertArrayEquals(new int[] {4, 5}, input);
    }

    private static List<Object> toList(Iterator it) {
        List<Object> result = new ArrayList<Object>();
        while (it.hasNext()) {
            result.add(it.next());
        }
        return result;
    }
}

package org.apache.commons.jxpath.util;

import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.NoSuchElementException;

import static org.junit.Assert.*;

public class IterateTests {

    @Test
    public void testNullReturnsEmptyIterator() {
        Iterator it = ValueUtils.iterate(null);
        assertNotNull(it);
        assertFalse(it.hasNext());
        try {
            it.next();
            fail("Expected NoSuchElementException");
        } catch (NoSuchElementException expected) {
        }
    }

    @Test
    public void testEmptyPrimitiveArrayReturnsEmptyIterator() {
        Iterator it = ValueUtils.iterate(new int[0]);
        assertNotNull(it);
        assertFalse(it.hasNext());
    }

    @Test
    public void testPrimitiveArrayIsIteratedInOrder() {
        int[] input = new int[] {1, 2, 3};
        Iterator it = ValueUtils.iterate(input);
        assertEquals(Arrays.asList(1, 2, 3), toList(it));
        assertArrayEquals(new int[] {1, 2, 3}, input);
    }

    @Test
    public void testMultiDimensionalArrayIsIteratedAsElements() {
        String[][] input = new String[][] {{"a", "b"}, {"c"}};
        Iterator it = ValueUtils.iterate(input);
        List<Object> result = toList(it);
        assertEquals(2, result.size());
        assertTrue(result.get(0) instanceof String[]);
        assertTrue(result.get(1) instanceof String[]);
        assertArrayEquals(new String[] {"a", "b"}, (String[]) result.get(0));
        assertArrayEquals(new String[] {"c"}, (String[]) result.get(1));
    }

    @Test
    public void testCollectionIsIteratedInOrderAndSourceCollectionUnchanged() {
        List<String> input = new LinkedList<String>(Arrays.asList("x", "y", "z"));
        Iterator it = ValueUtils.iterate(input);
        assertEquals(Arrays.asList("x", "y", "z"), toList(it));
        assertEquals(Arrays.asList("x", "y", "z"), input);
    }

    @Test
    public void testIteratorIsIndependentFromSubsequentCollectionModification() {
        List<Integer> input = new ArrayList<Integer>(Arrays.asList(1, 2, 3));
        Iterator it = ValueUtils.iterate(input);
        input.clear();
        input.add(99);
        assertEquals(Arrays.asList(1, 2, 3), toList(it));
    }

    @Test
    public void testCharSequenceIsIteratedAsCharacters() {
        Iterator it = ValueUtils.iterate(new StringBuilder("Az"));
        List<Object> result = toList(it);
        assertEquals(Arrays.asList(Character.valueOf('A'), Character.valueOf('z')), result);
    }

    @Test
    public void testCharSequenceWithUnicodeSupplementaryCharsIteratesPerCharUnit() {
        String value = "\uD83D\uDE00"; // smiling face, represented by two char values
        Iterator it = ValueUtils.iterate(value);
        List<Object> result = toList(it);
        assertEquals(2, result.size());
        assertEquals(Character.valueOf(value.charAt(0)), result.get(0));
        assertEquals(Character.valueOf(value.charAt(1)), result.get(1));
    }

    @Test
    public void testEmptyCharSequenceReturnsEmptyIterator() {
        Iterator it = ValueUtils.iterate("");
        assertNotNull(it);
        assertFalse(it.hasNext());
    }

    @Test
    public void testSingleObjectIsWrappedInSingletonIterator() {
        Object obj = new Object();
        Iterator it = ValueUtils.iterate(obj);
        assertTrue(it.hasNext());
        assertSame(obj, it.next());
        assertFalse(it.hasNext());
        try {
            it.next();
            fail("Expected NoSuchElementException");
        } catch (NoSuchElementException expected) {
        }
    }

    @Test
    public void testExistingIteratorIsTreatedAsSingleObjectNotConsumed() {
        List<String> source = Arrays.asList("a", "b");
        Iterator<String> original = source.iterator();
        Iterator it = ValueUtils.iterate(original);

        assertTrue(it.hasNext());
        assertSame(original, it.next());
        assertFalse(it.hasNext());

        assertTrue(original.hasNext());
        assertEquals("a", original.next());
    }

    @Test
    public void testArrayContainingNullElementPreservesNull() {
        Object[] input = new Object[] {"x", null, "y"};
        Iterator it = ValueUtils.iterate(input);
        assertEquals(Arrays.asList("x", null, "y"), toList(it));
    }

    @Test
    public void testInputArrayRemainsUnchangedAfterIteration() {
        String[] input = new String[] {"p", "q"};
        Iterator it = ValueUtils.iterate(input);
        assertEquals("p", it.next());
        assertEquals("q", it.next());
        assertArrayEquals(new String[] {"p", "q"}, input);
    }

    @Test
    public void testIteratorFromCollectionHasNoExtraElements() {
        List<String> input = Arrays.asList("solo");
        Iterator it = ValueUtils.iterate(input);
        assertTrue(it.hasNext());
        assertEquals("solo", it.next());
        assertFalse(it.hasNext());
    }

    private static List<Object> toList(Iterator it) {
        List<Object> result = new ArrayList<Object>();
        while (it.hasNext()) {
            result.add(it.next());
        }
        return result;
    }
}
